class_name SymbolDef
extends Resource

enum Tier { LOW, PREMIUM, WILD, HAZARD }

@export var id: StringName
@export var display_name: String = ""
@export var tier: Tier = Tier.LOW
@export var texture: Texture2D
@export var base_weight: float = 1.0

class_name CombatRNG
extends RefCounted

var _rng := RandomNumberGenerator.new()


func set_seed(s: int) -> void:
	_rng.seed = s


func randf() -> float:
	return _rng.randf()


func randi_range(a: int, b: int) -> int:
	return _rng.randi_range(a, b)

class_name GridManager
extends Node

const COLS := 5
const ROWS := 5

## cells[row][col] : SymbolDef or null
var cells: Array = []
## flags[row][col] : Dictionary (reserved for hazards / locks later)
var flags: Array = []

signal grid_populated
signal cells_cleared(coords: Array)
signal symbols_fell(moves: Array)
signal symbols_spawned(spawns: Array)


func _ready() -> void:
	_ensure_arrays()


func _ensure_arrays() -> void:
	cells.clear()
	flags.clear()
	for r in ROWS:
		var row: Array = []
		var frow: Array = []
		for c in COLS:
			row.append(null)
			frow.append({})
		cells.append(row)
		flags.append(frow)


func get_cell(p: Vector2i) -> SymbolDef:
	if not _in_bounds(p):
		return null
	return cells[p.y][p.x]


func set_cell(p: Vector2i, sym: SymbolDef) -> void:
	if not _in_bounds(p):
		return
	cells[p.y][p.x] = sym


func _in_bounds(p: Vector2i) -> bool:
	return p.x >= 0 and p.x < COLS and p.y >= 0 and p.y < ROWS


func populate(rng: CombatRNG, pool: Array, weights: Dictionary) -> void:
	_ensure_arrays()
	for r in ROWS:
		for c in COLS:
			cells[r][c] = _draw_symbol(rng, pool, weights)
	grid_populated.emit()


func _draw_symbol(rng: CombatRNG, pool: Array, weights: Dictionary) -> SymbolDef:
	if pool.is_empty():
		return null
	var total := 0.0
	for s in pool:
		var sym := s as SymbolDef
		if sym == null:
			continue
		total += _weight_for(sym, weights)
	if total <= 0.0:
		return pool[0] as SymbolDef
	var pick := rng.randf() * total
	var acc := 0.0
	for s in pool:
		var sym := s as SymbolDef
		if sym == null:
			continue
		acc += _weight_for(sym, weights)
		if pick <= acc:
			return sym
	return pool.back() as SymbolDef


func _weight_for(sym: SymbolDef, weights: Dictionary) -> float:
	if weights.has(sym.id):
		return float(weights[sym.id])
	return sym.base_weight


## Clears listed coords to null. Does not emit.
func clear_cells(coords: Array) -> void:
	for p in coords:
		var v := p as Vector2i
		set_cell(v, null)


## Returns moves: Array of { "from": Vector2i, "to": Vector2i }
func apply_gravity() -> Array:
	var moves: Array = []
	for c in COLS:
		var write_row := ROWS - 1
		for read_row in range(ROWS - 1, -1, -1):
			var sym: SymbolDef = cells[read_row][c]
			if sym == null:
				continue
			if read_row != write_row:
				cells[read_row][c] = null
				cells[write_row][c] = sym
				moves.append({"from": Vector2i(c, read_row), "to": Vector2i(c, write_row)})
			write_row -= 1
	if not moves.is_empty():
		symbols_fell.emit(moves)
	return moves


## Fills null cells from top with weighted random from pool.
func refill(rng: CombatRNG, pool: Array, weights: Dictionary) -> void:
	var spawns: Array = []
	for c in COLS:
		for r in ROWS:
			if cells[r][c] != null:
				continue
			var sym := _draw_symbol(rng, pool, weights)
			cells[r][c] = sym
			spawns.append({"coord": Vector2i(c, r), "sym": sym})
	if not spawns.is_empty():
		symbols_spawned.emit(spawns)


func snapshot_ids() -> String:
	var parts: PackedStringArray = PackedStringArray()
	for r in ROWS:
		for c in COLS:
			var s: SymbolDef = cells[r][c]
			if s == null:
				parts.append(".")
			else:
				parts.append(String(s.id))
	return "|".join(parts)

class_name ClusterDetector
extends RefCounted

## DESIGN: Wild (tier WILD) matches the anchor symbol_id during flood fill.
## We do not start a new cluster from a wild-only anchor (skip wild as seed).
## Overlapping cluster membership: flood fill uses a global visited set, so each
## cell belongs to at most one cluster per detection pass (standard match-3).
## (Design doc "wild in multiple clusters" applies to resolution UX / future rules;
## detection uses disjoint components.)
##
## Centroid for wild drop uses integer division on sum of coords (trunc toward 0);
## for non-negative 5x5 coords this matches floor — tie-break toward top-left cluster mass.


static func find_clusters(cells: Array) -> Array:
	var clusters: Array = []
	var visited: Dictionary = {}
	for r in ROWS:
		for c in COLS:
			var p := Vector2i(c, r)
			if visited.has(p):
				continue
			var sym: SymbolDef = cells[r][c]
			if sym == null:
				visited[p] = true
				continue
			if sym.tier == SymbolDef.Tier.HAZARD:
				visited[p] = true
				continue
			if sym.tier == SymbolDef.Tier.WILD:
				continue
			var anchor_id: StringName = sym.id
			var component: Array = _flood_fill(cells, visited, p, anchor_id)
			for cell in component:
				visited[cell] = true
			if component.size() >= 3:
				clusters.append({"symbol_id": anchor_id, "cells": component})
	return clusters


const ROWS := GridManager.ROWS
const COLS := GridManager.COLS


static func _flood_fill(cells: Array, visited: Dictionary, start: Vector2i, anchor_id: StringName) -> Array:
	var stack: Array[Vector2i] = [start]
	var out: Array = []
	while not stack.is_empty():
		var p: Vector2i = stack.pop_back()
		if visited.has(p):
			continue
		if p.x < 0 or p.x >= COLS or p.y < 0 or p.y >= ROWS:
			continue
		var sym: SymbolDef = cells[p.y][p.x]
		if sym == null:
			continue
		if sym.tier == SymbolDef.Tier.HAZARD:
			continue
		if sym.tier == SymbolDef.Tier.WILD:
			visited[p] = true
			out.append(p)
			for dir in _DIRS:
				var np := p + dir
				if not visited.has(np):
					stack.append(np)
			continue
		if sym.id != anchor_id:
			continue
		visited[p] = true
		out.append(p)
		for dir in _DIRS:
			var np := p + dir
			if not visited.has(np):
				stack.append(np)
	return out


static var _DIRS: Array[Vector2i] = [
	Vector2i(1, 0),
	Vector2i(-1, 0),
	Vector2i(0, 1),
	Vector2i(0, -1),
]


static func centroid_cell(cluster_cells: Array) -> Vector2i:
	var sx := 0
	var sy := 0
	for p in cluster_cells:
		var v := p as Vector2i
		sx += v.x
		sy += v.y
	var n: int = cluster_cells.size()
	if n == 0:
		return Vector2i.ZERO
	return Vector2i(int(sx / n), int(sy / n))

class_name ClusterDetector
extends RefCounted

## DESIGN: Wild (tier WILD) matches the anchor symbol_id during flood fill.
## Clusters are 4-connected components of cells where every non-wild symbol has
## the same id as the anchor, and WILD cells may connect matching symbols.
## We never start a flood from a wild-only cell (no anchor id).
##
## Disjoint components: each cell appears in at most one winning cluster per pass.
##
## Centroid: integer division on sum of coords (non-negative grid → trunc toward 0
## equals floor); deterministic for Phase 1.

const ROWS := GridManager.ROWS
const COLS := GridManager.COLS

static var _DIRS: Array[Vector2i] = [
	Vector2i(1, 0),
	Vector2i(-1, 0),
	Vector2i(0, 1),
	Vector2i(0, -1),
]


static func find_clusters(cells: Array) -> Array:
	var clusters: Array = []
	var visited: Dictionary = {}
	for r in ROWS:
		for c in COLS:
			var p := Vector2i(c, r)
			if visited.has(p):
				continue
			var sym: SymbolDef = cells[r][c]
			if sym == null:
				visited[p] = true
				continue
			if sym.tier == SymbolDef.Tier.HAZARD:
				visited[p] = true
				continue
			if sym.tier == SymbolDef.Tier.WILD:
				continue
			var anchor_id: StringName = sym.id
			var component: Array = _flood_fill(cells, visited, p, anchor_id)
			for cell in component:
				visited[cell] = true
			if component.size() >= 3:
				clusters.append({"symbol_id": anchor_id, "cells": component})
	# Wilds never used as anchors; mark stragglers so we never spin forever on orphan wilds.
	for r in ROWS:
		for c in COLS:
			var p2 := Vector2i(c, r)
			if visited.has(p2):
				continue
			var wsym: SymbolDef = cells[r][c]
			if wsym != null and wsym.tier == SymbolDef.Tier.WILD:
				visited[p2] = true
	return clusters


static func _flood_fill(cells: Array, visited: Dictionary, start: Vector2i, anchor_id: StringName) -> Array:
	var stack: Array[Vector2i] = [start]
	var out: Array = []
	while not stack.is_empty():
		var p: Vector2i = stack.pop_back()
		if visited.has(p):
			continue
		if p.x < 0 or p.x >= COLS or p.y < 0 or p.y >= ROWS:
			continue
		var sym: SymbolDef = cells[p.y][p.x]
		if sym == null or sym.tier == SymbolDef.Tier.HAZARD:
			continue
		if sym.tier == SymbolDef.Tier.WILD:
			visited[p] = true
			out.append(p)
			for dir in _DIRS:
				stack.append(p + dir)
			continue
		if sym.id != anchor_id:
			continue
		visited[p] = true
		out.append(p)
		for dir in _DIRS:
			stack.append(p + dir)
	return out


static func centroid_cell(cluster_cells: Array) -> Vector2i:
	var sx := 0
	var sy := 0
	for p in cluster_cells:
		var v := p as Vector2i
		sx += v.x
		sy += v.y
	var n: int = cluster_cells.size()
	if n == 0:
		return Vector2i.ZERO
	return Vector2i(int(sx / n), int(sy / n))

extends Node2D

enum State { IDLE, SPINNING }

const DEBUG_AWAIT_TIMEOUT_SEC := 2.0

@export var symbol_resources: Array[Resource] = []

@onready var grid: GridManager = $GridManager
@onready var grid_ui: GridContainer = $GridUI
@onready var multiplier_label: Label = $MultiplierLabel

var rng := CombatRNG.new()
var multiplier := CombatMultiplier.new()
var wild_symbol: SymbolDef
var low_symbol_pool: Array[SymbolDef] = []

var _state: State = State.IDLE
var _weights: Dictionary = {}


func _ready() -> void:
	_load_symbols_from_export()
	grid.grid_populated.connect(_on_grid_populated)
	grid.cells_cleared.connect(_on_cells_cleared)
	grid.symbols_fell.connect(_on_symbols_fell)
	grid.symbols_spawned.connect(_on_symbols_spawned)
	_refresh_multiplier_label()


func _load_symbols_from_export() -> void:
	low_symbol_pool.clear()
	wild_symbol = null
	for res in symbol_resources:
		var sd := res as SymbolDef
		if sd == null:
			continue
		if sd.tier == SymbolDef.Tier.WILD:
			wild_symbol = sd
		elif sd.tier == SymbolDef.Tier.LOW:
			low_symbol_pool.append(sd)
			_weights[sd.id] = sd.base_weight
	if wild_symbol == null:
		push_error("CombatRoot: assign wild SymbolDef in symbol_resources.")
	if low_symbol_pool.is_empty():
		push_error("CombatRoot: assign at least one LOW symbol in symbol_resources.")


func get_state() -> int:
	return _state as int


func get_multiplier_value() -> int:
	return multiplier.value


func setup_new_grid(seed_value: int) -> void:
	rng.seed(seed_value)
	grid.populate(rng, low_symbol_pool, _weights)
	_refresh_cells_visual()


func spin() -> void:
	if _state != State.IDLE:
		return
	_state = State.SPINNING
	multiplier.reset()
	_refresh_multiplier_label()
	while true:
		var clusters: Array = ClusterDetector.find_clusters(grid.cells)
		if clusters.is_empty():
			break
		await _resolve_clusters(clusters)
		await _apply_gravity_and_refill()
	_state = State.IDLE
	_refresh_multiplier_label()


## Headless / determinism: same logic as spin() without awaiting the renderer.
func spin_sync() -> void:
	if _state != State.IDLE:
		return
	_state = State.SPINNING
	multiplier.reset()
	while true:
		var clusters: Array = ClusterDetector.find_clusters(grid.cells)
		if clusters.is_empty():
			break
		_resolve_clusters_sync(clusters)
		_apply_gravity_and_refill_sync()
	_state = State.IDLE


func serialize_spin_result() -> String:
	return "%s|%d" % [grid.snapshot_ids(), multiplier.value]


func _resolve_clusters(clusters: Array) -> void:
	_resolve_clusters_impl(clusters)
	await _await_frame_safe()


func _resolve_clusters_sync(clusters: Array) -> void:
	_resolve_clusters_impl(clusters)


func _resolve_clusters_impl(clusters: Array) -> void:
	var all_cleared: Array = []
	for cl in clusters:
		for p in cl["cells"]:
			all_cleared.append(p)
	grid.cells_cleared.emit(all_cleared)
	for p in all_cleared:
		grid.set_cell(p, null)
	var sorted_clusters: Array = clusters.duplicate()
	sorted_clusters.sort_custom(_compare_clusters_sort)
	for cl in sorted_clusters:
		var cells: Array = cl["cells"]
		var drop_cell := _wild_drop_cell_in_footprint(cells)
		grid.set_cell(drop_cell, wild_symbol)
		multiplier.add(1)
	_refresh_cells_visual()
	_refresh_multiplier_label()


func _compare_clusters_sort(a: Variant, b: Variant) -> bool:
	var ka: Vector2i = _cluster_sort_key((a as Dictionary)["cells"] as Array)
	var kb: Vector2i = _cluster_sort_key((b as Dictionary)["cells"] as Array)
	if ka.y != kb.y:
		return ka.y < kb.y
	return ka.x < kb.x


func _cluster_sort_key(cluster_cells: Array) -> Vector2i:
	var best := Vector2i(999, 999)
	for p in cluster_cells:
		var v := p as Vector2i
		if v.y < best.y or (v.y == best.y and v.x < best.x):
			best = v
	return best


func _wild_drop_cell_in_footprint(cluster_cells: Array) -> Vector2i:
	var ideal := ClusterDetector.centroid_cell(cluster_cells)
	for p in cluster_cells:
		var v := p as Vector2i
		if v == ideal:
			return ideal
	var best: Vector2i = cluster_cells[0] as Vector2i
	var best_dist := 999999
	for p in cluster_cells:
		var v := p as Vector2i
		var d: int = absi(v.x - ideal.x) + absi(v.y - ideal.y)
		if d < best_dist or (d == best_dist and (v.y < best.y or (v.y == best.y and v.x < best.x))):
			best_dist = d
			best = v
	return best


func _apply_gravity_and_refill() -> void:
	grid.apply_gravity()
	grid.refill(rng, low_symbol_pool, _weights)
	_refresh_cells_visual()
	await _await_frame_safe()


func _apply_gravity_and_refill_sync() -> void:
	grid.apply_gravity()
	grid.refill(rng, low_symbol_pool, _weights)
	_refresh_cells_visual()


func _await_frame_safe() -> void:
	var tree := get_tree()
	if tree == null:
		return
	var frame_done := false
	var on_frame := func() -> void:
		frame_done = true
	tree.process_frame.connect(on_frame, CONNECT_ONE_SHOT)
	var elapsed := 0.0
	while not frame_done:
		await tree.create_timer(0.05).timeout
		elapsed += 0.05
		if elapsed >= DEBUG_AWAIT_TIMEOUT_SEC:
			push_warning("CombatRoot: await exceeded %.1fs (renderer stall?)" % DEBUG_AWAIT_TIMEOUT_SEC)
			return


func _on_grid_populated() -> void:
	_refresh_cells_visual()


func _on_cells_cleared(_coords: Array) -> void:
	pass


func _on_symbols_fell(_moves: Array) -> void:
	pass


func _on_symbols_spawned(_spawns: Array) -> void:
	pass


func _refresh_multiplier_label() -> void:
	if multiplier_label:
		multiplier_label.text = "Multiplier: %d×" % multiplier.value


func _refresh_cells_visual() -> void:
	var idx := 0
	for child in grid_ui.get_children():
		var tr := child as TextureRect
		if tr == null:
			continue
		var r: int = idx / GridManager.COLS
		var c: int = idx % GridManager.COLS
		var sym: SymbolDef = grid.cells[r][c]
		if sym != null and sym.texture != null:
			tr.texture = sym.texture
		else:
			tr.texture = null
		idx += 1

